import {repo, scenes, sceneImage, themedCapture, sleeve, capture, download, header, footer, requirements, sceneControls} from './data.js';

function browseSection(caption = 'Your whole collection, close by.') {
  return `<section class="browse-section shell"><div class="browse-heading"><p class="eyebrow">Beyond Now Playing</p><h2>${caption}</h2></div>${capture('home.png', 'Coda library with album artwork, artists, and a visible listening queue.')}</section>`;
}

const layouts = {
  1: () => `${header()}<main><section class="showroom-intro"><p class="eyebrow">A native player for your music</p><h1>Your albums.<br>On your Mac.</h1><p class="intro-copy">A quiet home for your Navidrome library.</p><div class="intro-actions">${download()}<a class="text-link" href="${repo}#install" target="_blank" rel="noopener">Installation help</a></div>${requirements()}</section><section class="showroom-stage shell">${sceneImage()}${sceneControls()}</section><section class="collection-section shell"><div class="section-heading"><p class="eyebrow">Albums first</p><h2>Your whole collection,<br>close by.</h2></div><div class="two-up"><figure>${capture('home.png', 'Coda library, showing artists, albums, and the listening queue.')}<figcaption>Find something worth sitting down for.</figcaption></figure><figure>${capture('album.png', 'Coda album view with artwork, track list, and queue.')}<figcaption>Put on an album. Keep the queue close.</figcaption></figure></div><p class="compatibility-note">For Navidrome and compatible OpenSubsonic servers.</p></section></main>${footer()}`,

  2: (initial) => `${header(true)}<main><section class="editorial-layout"><div class="editorial-copy"><p class="eyebrow">A player for the album</p><h1>An album.<br>An evening.</h1><p class="intro-copy">Your Navidrome library,<br>beautifully at home on Mac.</p><div class="editorial-line"></div><p class="editorial-note">Choose something.<br>Let it play.</p><p class="requirements">macOS 26+ · Apple silicon<br>Navidrome / OpenSubsonic</p></div><div class="editorial-print">${sceneImage(initial)}<div class="quiet-preview-controls"><button class="motion-button" type="button" data-motion aria-pressed="false">Pause preview</button></div></div></section><section class="editorial-spread"><div class="spread-label"><span>Inside Coda</span><span>Browse. Choose. Listen.</span></div><div class="two-up"><figure>${themedCapture(initial, 'home')}<figcaption>Your collection.</figcaption></figure><figure>${themedCapture(initial, 'album')}<figcaption>Something for tonight.</figcaption></figure></div><div class="quiet-preview-controls"><button class="motion-button" type="button" data-motion aria-pressed="false">Pause preview</button></div></section></main>${footer()}`,

  3: (initial) => `${header()}<main><section class="cinema-layout"><div class="cinema-copy"><p class="eyebrow">Coda for macOS</p><h1>Your music,<br>in full view.</h1><p class="intro-copy">Albums, artwork, and the queue.<br>A native player for your<br>Navidrome library.</p>${download()}${requirements()}<p class="cinema-aside">Different album.<br><span>Different atmosphere.</span></p></div><div class="cinema-screen">${sceneImage(initial)}<div class="quiet-preview-controls"><button class="motion-button" type="button" data-motion aria-pressed="false">Pause preview</button></div></div></section><section class="cinema-collection shell"><div class="section-heading"><p class="eyebrow">Made for listening</p><h2>Pick an album. Stay awhile.</h2><p class="intro-copy">Original-quality, gapless playback. Navidrome and OpenSubsonic.</p></div><div class="two-up"><figure>${themedCapture(initial, 'home')}<figcaption>Your collection, close by.</figcaption></figure><figure>${themedCapture(initial, 'album')}<figcaption>An album, and whatever comes next.</figcaption></figure></div><div class="quiet-preview-controls"><button class="motion-button" type="button" data-motion aria-pressed="false">Pause preview</button></div></section></main>${footer()}`,

  4: () => `${header(true)}<main><section class="selector-layout"><div class="selector-copy"><p class="eyebrow">Your collection sets the tone</p><h1>Every album<br>changes<br>the room.</h1><p class="intro-copy">A native Mac player for<br>Navidrome and OpenSubsonic.</p><div class="sleeve-selector" aria-label="Choose an album scene">${scenes.map((scene, i) => `<button type="button" class="sleeve-button" data-scene="${i}" aria-pressed="${i === 0}" aria-label="Show ${scene.album} by ${scene.artist}">${sleeve(i)}</button>`).join('')}</div><p class="selector-hint">Choose a sleeve.</p><div class="selected-album" data-scene-caption aria-live="polite">Sigh <span>— Goh-Ka</span></div>${requirements()}</div><div class="selector-screen">${sceneImage()}</div></section>${browseSection('Your collection.<br>One good place.')}</main>${footer()}`,

  5: () => `${header(true)}<main><section class="room"><div class="room-stage">${sceneImage()}</div><div class="room-caption"><div><h1>Your albums. On your Mac.</h1><p>A native player for Navidrome and OpenSubsonic.</p></div><div class="room-utility"><span data-scene-caption>Sigh — Goh-Ka</span><button class="motion-button" type="button" data-motion aria-pressed="false">Pause preview</button></div></div></section>${browseSection('And your whole collection, close by.')}<div class="room-requirements">${requirements()}</div></main>${footer()}`,

  6: () => `${header(true)}<main class="poster"><div class="poster-heading"><h1>Your albums. On your Mac.</h1><p class="intro-copy">A native player for your Navidrome or OpenSubsonic library.</p>${requirements()}</div><div class="view-switcher" aria-label="Choose a Coda screenshot"><button type="button" data-view="now" aria-pressed="true">Now Playing</button><button type="button" data-view="home" aria-pressed="false">Browse</button><button type="button" data-view="album" aria-pressed="false">Album</button></div><div class="poster-media" id="view-frame">${sceneImage()}</div><p class="poster-caption" id="view-caption" aria-live="polite">Now Playing. Artwork at the center; your queue in view.</p></main>${footer()}`,

  7: () => `${header()}<main class="contact-sheet"><div class="contact-grid"><figure class="contact-main">${sceneImage()}<figcaption>01 / Sigh</figcaption></figure><figure class="contact-echo"><div class="aperture"><img src="assets/satriani.png" alt="Detail of Coda's purple atmosphere around The Elephants of Mars artwork." width="1836" height="1572"></div><figcaption>02 / Joe Satriani</figcaption></figure><figure class="contact-echo"><div class="aperture"><img src="assets/pizza.png" alt="Detail of Coda's magenta atmosphere around Press Start artwork." width="1836" height="1572"></div><figcaption>03 / Samurai Pizza Cats</figcaption></figure></div><div class="contact-caption"><div><p class="eyebrow">One player. Different lights.</p><h1>Made for your music.</h1><p class="intro-copy">Navidrome + OpenSubsonic for macOS.</p></div><div>${download()}${requirements()}</div></div></main>${footer()}`,

  8: () => `${header()}<main class="journey"><div class="journey-heading"><div><p class="eyebrow">From your collection to your evening</p><h1>Find an album.<br>Stay a while.</h1><p class="intro-copy">Your Navidrome library, on your Mac.</p></div><div class="journey-actions">${download()}<button type="button" class="walkthrough-button" data-walkthrough>Take a look <span aria-hidden="true">▷</span></button>${requirements()}</div></div><div class="journey-media" id="journey-frame">${sceneImage(3)}</div><div class="journey-chapters" aria-label="Choose a screenshot in the walkthrough"><button type="button" data-chapter="0" aria-pressed="false"><span>01</span>Your collection.</button><button type="button" data-chapter="1" aria-pressed="false"><span>02</span>This one.</button><button type="button" data-chapter="2" aria-pressed="true"><span>03</span>Now, listen.</button></div><p class="journey-note">Three screenshot views · Navidrome and OpenSubsonic</p></main>${footer()}`,
};

export function renderLayout(id, initialScene = 0) { return (layouts[id] || layouts[1])(initialScene); }
